import type { APIRoute } from 'astro';
import { SITE_URL } from '../config';

// Allows everything and points crawlers at the sitemap generated by @astrojs/sitemap.
// Uses SITE_URL from config rather than Astro.site, which is not available inside endpoints in Astro 6+.
export const GET: APIRoute = () =>
  new Response(`User-agent: *\nAllow: /\n\nSitemap: ${SITE_URL}/sitemap-index.xml\n`, {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  });
